import type { Metadata } from "next";
import { SITE_CONFIG } from "@/lib/constants/site";

const DEFAULT_OG_IMAGE = "/images/webflow/Group-47047.png";

type OgType = "website" | "article" | "profile";

export function createMetadata({
  title,
  description,
  path = "",
  ogImage = DEFAULT_OG_IMAGE,
  type = "website",
  noindex = false,
  publishedTime,
  authors,
}: {
  title: string;
  description: string;
  path?: string;
  ogImage?: string;
  type?: OgType;
  noindex?: boolean;
  publishedTime?: string;
  authors?: string[];
}): Metadata {
  const url = `${SITE_CONFIG.url}${path}`;
  const ogImageUrl = ogImage.startsWith("http")
    ? ogImage
    : `${SITE_CONFIG.url}${ogImage}`;

  return {
    title,
    description,
    alternates: {
      canonical: url,
    },
    robots: noindex
      ? { index: false, follow: false }
      : {
          index: true,
          follow: true,
          googleBot: {
            index: true,
            follow: true,
            "max-image-preview": "large",
            "max-snippet": -1,
            "max-video-preview": -1,
          },
        },
    openGraph: {
      title,
      description,
      url,
      siteName: SITE_CONFIG.name,
      type,
      locale: "en_US",
      images: [
        {
          url: ogImageUrl,
          width: 1200,
          height: 630,
          alt: title,
        },
      ],
      ...(publishedTime && type === "article" ? { publishedTime } : {}),
      ...(authors && type === "article" ? { authors } : {}),
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [ogImageUrl],
    },
  };
}

import { SITE_CONFIG } from "@/lib/constants/site";

type SchemaObject = Record<string, unknown>;

interface JsonLdProps {
  data: SchemaObject | SchemaObject[];
  id?: string;
}

/**
 * Render a JSON-LD <script> block.
 * Pass a single schema object or an array (will be emitted as @graph).
 */
export function JsonLd({ data, id }: JsonLdProps) {
  const payload = Array.isArray(data)
    ? { "@context": "https://schema.org", "@graph": data }
    : data;

  return (
    <script
      id={id}
      type="application/ld+json"
      dangerouslySetInnerHTML={{ __html: JSON.stringify(payload) }}
    />
  );
}

export interface BreadcrumbItem {
  name: string;
  path: string;
}

/**
 * Build BreadcrumbList JSON-LD from a Home → … → current path.
 */
export function breadcrumbSchema(items: BreadcrumbItem[]): SchemaObject {
  const list = [
    { name: "Home", path: "/" },
    ...items,
  ];
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: list.map((item, idx) => ({
      "@type": "ListItem",
      position: idx + 1,
      name: item.name,
      item: `${SITE_CONFIG.url}${item.path}`,
    })),
  };
}

