  const tOK = tLen<=60 ? 'OK' : 'LONG';
  const dOK = (dLen>=140 && dLen<=160) ? 'OK' : (dLen<140?'SHORT':'LONG');
  console.log(\`[t:\${tLen} \${tOK}|d:\${dLen} \${dOK}] \${f}\`);
